from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=2 and not (g[i][j]==0):
                pass
    # all nonzero-color comps incl 0
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append((c,cells))
    return out
def norm(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    y0,x0=min(ys),min(xs)
    return tuple(sorted((y-y0,x-x0) for y,x in cells))
